/** Partial equation coloring on equations GENERATED BY Sketch-to-Slides (the real local-model output for the PPO capture,
 * replayed through the real conversion; no network): the same pick → color → reset → undo/redo → save/reopen → PDF/PPTX
 * behavior as for `/math` equations (tests/math-leaf-color-ui.mjs, math-leaf-drag.mjs).
 * Display equation: drag over two symbols, Shift+→ extends the range, color blue, 기본 색상 resets. Inline equation (in
 * the paper sentence): drag over its symbols and color them. Then Undo/Redo, save → reopen, PDF, PPTX.
 * Run: node tests/math-leaf-sketch.mjs
 */
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { createServer } from 'vite';
import JSZip from 'jszip';
import { testElectronEnv } from './electron-env.mjs';
import { launchElectron, startViteServer, stopElectron } from './test-ports.mjs';

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const profile = await mkdtemp(path.join(tmpdir(), 'mathslides-leaf-sketch-'));
const pdfDir = path.join(profile, 'pdf');
await mkdir(pdfDir);
let debugPort;
const { server, url: devUrl } = await startViteServer(createServer, { root, configLoader: 'runner', cacheDir: path.join(profile, 'vite'), logLevel: 'error' });
const wrapper = path.join(profile, 'main.cjs');
await writeFile(wrapper, `const { app } = require('electron'); app.setPath('userData', ${JSON.stringify(profile)}); require(${JSON.stringify(path.join(root, 'electron/main.cjs'))});\n`);

let electron, socket, id = 0;
const pending = new Map();
const pause = (ms = 150) => new Promise((r) => setTimeout(r, ms));
async function until(fn, message, timeout = 30000) { const t = Date.now(); while (Date.now() - t < timeout) { try { const v = await fn(); if (v) return v; } catch {} await pause(150); } throw new Error(message); }
const send = (method, params = {}) => new Promise((resolve, reject) => { const k = ++id; pending.set(k, { resolve, reject }); socket.send(JSON.stringify({ id: k, method, params })); });
async function evaluate(expression) { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result.value; }
const clickButton = (text) => evaluate(`(() => { const b = [...document.querySelectorAll('button')].find((b) => b.textContent.trim() === ${JSON.stringify(text)}); if (!b || b.disabled) throw Error('No enabled button ' + ${JSON.stringify(text)}); b.click(); return true; })()`);
const click = async (sel) => {
  const r = await evaluate(`(() => { const e = document.querySelector(${JSON.stringify(sel)}); if (!e) throw Error('Missing ' + ${JSON.stringify(sel)}); const r = e.getBoundingClientRect(); return {x: r.x + r.width / 2, y: r.y + r.height / 2}; })()`);
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', button: 'left', clickCount: 1, ...r });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', button: 'left', clickCount: 1, ...r }); await pause(200);
};
const key = async (k, modifiers = 0) => { const code = { ArrowRight: 39, ArrowLeft: 37 }[k] ?? 0; await send('Input.dispatchKeyEvent', { type: 'keyDown', key: k, code: k, windowsVirtualKeyCode: code, modifiers }); await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code: k, windowsVirtualKeyCode: code, modifiers }); await pause(200); };
const TEXT = '.propsbar button[title^="글자 색 (Text Color)"]';
const LEAF = (sel) => sel + ' g[data-mml-node="mi"], ' + sel + ' g[data-mml-node="mn"], ' + sel + ' g[data-mml-node="mo"]';
const leafRect = (sel, i) => evaluate(`(() => { const g = document.querySelectorAll(${JSON.stringify(LEAF(sel))})[${i}]; const r = g.getBoundingClientRect(); return {l: r.left, r: r.right, cx: (r.left + r.right) / 2, cy: (r.top + r.bottom) / 2}; })()`);
const fills = (sel) => evaluate(`[...document.querySelectorAll(${JSON.stringify(LEAF(sel))})].map((g) => g.getAttribute('fill'))`);
async function drag(from, to) {
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', button: 'left', clickCount: 1, x: from.x, y: from.y });
  for (let k = 1; k <= 6; k++) await send('Input.dispatchMouseEvent', { type: 'mouseMoved', button: 'left', x: from.x + (to.x - from.x) * k / 6, y: from.y + (to.y - from.y) * k / 6 });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', button: 'left', clickCount: 1, x: to.x, y: to.y }); await pause(250);
}
const B = '#2563EB';
/** Math nodes of a text element, with their stored partial colors. */
const mathNodes = (els) => els.flatMap((e) => { const out = []; const walk = (n) => { if (!n) return; if (n.type === 'mathBlock' || n.type === 'mathInline') out.push({ type: n.type, latex: n.attrs.latex, colors: n.attrs.colors ?? null }); n.content?.forEach(walk); }; walk(e.doc); return out; });
const slideEls = () => evaluate(`JSON.parse(JSON.stringify(store.getState().deck.slides.find((s) => s.id === store.getState().currentSlideId).elements))`);
const colorsOf = async (ids) => mathNodes((await slideEls()).filter((e) => ids.includes(e.id)));
const attrsOf = (elId, type) => evaluate(`(() => { const e = store.getState().deck.slides.find((s) => s.id === store.getState().currentSlideId).elements.find((x) => x.id === ${JSON.stringify(elId)}); let a; const walk = (n) => { if (n.type === ${JSON.stringify(type)} && !a) a = n.attrs; n.content?.forEach(walk); }; walk(e.doc); return JSON.stringify(a); })()`);

try {
  ({ child: electron, debugPort } = await launchElectron(require('electron'), [wrapper], {
    cwd: root,
    env: testElectronEnv({ ELECTRON_DEV_URL: devUrl, MATHSLIDES_SKETCH_FAKE: path.join(root, 'tests/fixtures/sketch/ppo-grpo.local.json'), MATHSLIDES_TEST_PDF_DIR: pdfDir, ANTHROPIC_API_KEY: '' }),
  }));
  electron.stderr.on('data', () => {});
  const target = await until(async () => (await (await fetch(`http://127.0.0.1:${debugPort}/json`)).json()).find((t) => t.type === 'page'), 'debug target');
  socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => socket.addEventListener('open', r, { once: true }));
  socket.addEventListener('message', (e) => { const d = JSON.parse(e.data); const p = pending.get(d.id); if (p) { pending.delete(d.id); d.error ? p.reject(Error(d.error.message)) : p.resolve(d.result); } });
  await send('Runtime.enable');
  await until(() => evaluate(`!!document.querySelector('.propsbar')`), 'app mount');
  await evaluate(`(async () => {
    window.store = (await import('/src/store/store.ts')).useStore; window.active = (await import('/src/editor/active.ts')).getActiveEditor;
    window.insert = await import('/src/canvas/insert.ts'); window.persist = await import('/src/store/persistence.ts');
    window.testFiles = {};
    window.showSaveFilePicker = async ({suggestedName}) => ({name:suggestedName,createWritable:async()=>({write:async(blob)=>{testFiles[suggestedName]=[...new Uint8Array(await blob.arrayBuffer())]},close:async()=>{}})});
  })()`);

  // --- generate the equations with Sketch-to-Slides (real local-model output for the PPO capture, replayed) ---
  await evaluate(`store.getState().addSlide()`);
  await evaluate(`(async () => { const b = await (await fetch('/examples/sketches/ppo-grpo.png')).blob(); await insert.insertImageFiles([new File([b], 'ppo-grpo.png', { type: 'image/png' })]); })()`);
  const img = await until(() => evaluate(`store.getState().deck.slides.find((s) => s.id === store.getState().currentSlideId).elements.find((e) => e.type === 'image')`), 'image');
  const frame = { x: 100, y: 200, w: 1080, h: 406 };
  await evaluate(`store.getState().updateElements([${JSON.stringify(img.id)}], (d) => Object.assign(d, ${JSON.stringify(frame)})); store.getState().select([${JSON.stringify(img.id)}])`);
  await pause(200);
  await clickButton('Convert to Editable Slide');
  await until(async () => (await evaluate(`sketch.useSketch?.getState().phase`).catch(() => null)) === 'preview' || (await evaluate(`document.querySelector('.sk-footer')?.textContent.includes('Apply')`)), 'preview');
  await until(() => evaluate(`[...document.querySelectorAll('.sk-footer button')].some((b) => b.textContent.trim() === 'Apply' && !b.disabled)`), 'Apply enabled');
  const convIds = await evaluate(`(() => { const ids = [...document.querySelectorAll('.sk-preview [data-el-id]')].map((n) => n.dataset.elId); return ids; })()`);
  await clickButton('Apply');
  await until(() => evaluate(`!document.querySelector('.sk-dialog')`), 'applied');
  await evaluate(`store.getState().select([])`); await pause(500);
  const els = (await slideEls()).filter((e) => e.type === 'text' && JSON.stringify(e.doc).match(/math(Block|Inline)/));
  const block = els.find((e) => e.doc.content?.[0]?.type === 'mathBlock');
  const inlineEl = els.find((e) => e.doc.content?.some((p) => p.content?.some((n) => n.type === 'mathInline')));
  assert.ok(block && inlineEl, 'Sketch-to-Slides produced a display equation and a sentence with inline equations');
  const mathIds = [block.id, inlineEl.id];
  const before = await colorsOf(mathIds);
  assert.ok(before.every((m) => m.colors === null), 'generated equations start without partial colors');
  const latex0 = JSON.parse(await attrsOf(block.id, 'mathBlock')).latex;
  console.log('PASS equations generated by Sketch-to-Slides (display + ' + before.filter((m) => m.type === 'mathInline').length + ' inline)');

  // --- display equation: edit mode, drag over two symbols, Shift+→, color, 기본 색상 ---
  const BS = '.el.editing .math-block';
  await evaluate(`store.getState().startEditing(${JSON.stringify(block.id)})`);
  await until(() => evaluate(`!!document.querySelector('${BS} svg')`), 'math rendered while editing'); await pause(400);
  const a = await leafRect(BS, 0), b = await leafRect(BS, 1);
  await drag({ x: a.l + 1, y: a.cy }, { x: b.cx, y: b.cy });
  assert.deepEqual(await evaluate('store.getState().mathLeafSel?.leaves'), [0, 1], 'dragging picks the first two symbols of the generated equation');
  assert.equal(await evaluate('!!store.getState().mathEdit'), false, 'a drag does not open the LaTeX editor');
  await key('ArrowRight', 8); // Shift+→
  const ext = await evaluate('store.getState().mathLeafSel?.leaves');
  assert.deepEqual(ext, [0, 1, 2], 'Shift+→ extends the range by one symbol: ' + JSON.stringify(ext));
  await click(TEXT); await until(() => evaluate(`!!document.querySelector('.text-palette')`), 'palette');
  await click('.text-palette .standard-colors .text-swatch:nth-child(7)'); await pause(300);
  let attrs = JSON.parse(await attrsOf(block.id, 'mathBlock'));
  assert.equal(attrs.latex, latex0, 'the generated LaTeX is untouched');
  assert.deepEqual(attrs.colors.items.map((x) => x.i), [0, 1, 2]); assert.ok(attrs.colors.items.every((x) => x.c === B));
  assert.deepEqual((await fills(BS)).slice(0, 4), [B, B, B, null], 'only the picked symbols are blue');
  await click(TEXT); await until(() => evaluate(`!!document.querySelector('.text-palette')`), 'palette');
  await evaluate(`[...document.querySelectorAll('.text-palette .palette-other')].find((b) => b.textContent.includes('기본 색상')).click()`); await pause(300);
  assert.equal(JSON.parse(await attrsOf(block.id, 'mathBlock')).colors, null, '기본 색상 restores the default');
  await evaluate('active().commands.undo()'); await pause(200);
  assert.ok(JSON.parse(await attrsOf(block.id, 'mathBlock')).colors, 'undo brings the color back');
  await evaluate('active().commands.redo()'); await pause(200);
  assert.equal(JSON.parse(await attrsOf(block.id, 'mathBlock')).colors, null, 'redo resets again');
  await evaluate('active().commands.undo()'); await pause(200); // leave the three symbols blue for save/export
  await evaluate('store.getState().stopEditing()'); await pause(400);
  console.log('PASS display equation: drag, Shift+→, color, 기본 색상, undo/redo');

  // --- inline equation inside the paper sentence ---
  const IS = '.el.editing .math-inline';
  await evaluate(`store.getState().startEditing(${JSON.stringify(inlineEl.id)})`);
  await until(() => evaluate(`!!document.querySelector('${IS} svg')`), 'inline math rendered'); await pause(400);
  const n = await evaluate(`document.querySelectorAll(${JSON.stringify(LEAF(IS + ':nth-of-type(1)'))}).length`);
  const first = await evaluate(`(() => { const s = document.querySelector('${IS}'); const g = s.querySelectorAll('g[data-mml-node="mi"], g[data-mml-node="mn"], g[data-mml-node="mo"]'); const r0 = g[0].getBoundingClientRect(), r1 = g[g.length - 1].getBoundingClientRect(); return { from: { x: r0.left + 1, y: (r0.top + r0.bottom) / 2 }, to: { x: (r1.left + r1.right) / 2, y: (r1.top + r1.bottom) / 2 } }; })()`);
  await drag(first.from, first.to);
  const picked = await evaluate('store.getState().mathLeafSel');
  assert.ok(picked && picked.leaves.length >= 2, 'dragging over an inline equation of the sentence picks its symbols: ' + JSON.stringify(picked) + ' (leaves ' + n + ')');
  await click(TEXT); await until(() => evaluate(`!!document.querySelector('.text-palette')`), 'palette');
  await click('.text-palette .standard-colors .text-swatch:nth-child(1)'); await pause(300);
  const red = JSON.parse(await attrsOf(inlineEl.id, 'mathInline'));
  assert.ok(red.colors?.items.length >= 2 && red.colors.items.every((x) => x.c === '#DC2626'), 'inline symbols colored red: ' + JSON.stringify(red.colors));
  assert.equal(red.latex, '\\pi_{\\theta}', 'the inline LaTeX is untouched');
  await evaluate('store.getState().stopEditing()'); await pause(400);
  console.log('PASS inline equation inside a Sketch-to-Slides sentence: drag + color');

  // --- save → reopen ---
  const colored = await colorsOf(mathIds);
  assert.ok(colored.some((m) => m.colors), 'colors stored in the deck');
  await evaluate(`persist.saveProject(true)`);
  const name = await until(() => evaluate(`Object.keys(testFiles).find((k) => k.endsWith('.mslides'))`), 'saved');
  const text = Buffer.from(await evaluate(`testFiles[${JSON.stringify(name)}]`)).toString('utf8');
  const slideIdx = await evaluate(`store.getState().deck.slides.findIndex((s) => s.id === store.getState().currentSlideId)`);
  await evaluate(`store.getState().loadDeck(JSON.parse(JSON.stringify({ version: 1, title: 'blank', slides: [{ id: 'x', background: '#fff', elements: [], notes: '' }] })), {})`);
  await evaluate(`persist.openFromText(${JSON.stringify(text)}, null)`);
  await evaluate(`store.getState().goToSlide(store.getState().deck.slides[${slideIdx}].id)`); await pause(600);
  assert.deepEqual(await colorsOf(mathIds), colored, 'partial colors identical after save and reopen');
  assert.ok((await fills('.stage .slide .math-block')).some((f) => f === B), 'reopened slide renders the colored symbols');
  console.log('PASS save → reopen keeps the partial colors');

  // --- PDF and PPTX ---
  await evaluate(`import('/src/export/run.ts').then((m) => m.exportPdf())`);
  const pdfName = await until(async () => (await readdir(pdfDir)).find((f) => f.endsWith('.pdf')), 'PDF', 60000);
  assert.equal((await readFile(path.join(pdfDir, pdfName))).subarray(0, 4).toString(), '%PDF');
  await evaluate("import('/src/export/run.ts').then((m) => m.exportPptx())");
  const title = await evaluate('store.getState().deck.title');
  await until(() => evaluate(`testFiles[${JSON.stringify(title + '.pptx')}]?.length > 1000`), 'PPTX', 60000);
  const zip = await JSZip.loadAsync(Buffer.from(await evaluate(`testFiles[${JSON.stringify(title + '.pptx')}]`)));
  const media = Object.keys(zip.files).filter((f) => /^ppt\/media\/.+\.(svg|png)$/.test(f));
  let blueInMedia = false;
  for (const f of media.filter((m) => m.endsWith('.svg'))) if ((await zip.file(f).async('string')).toLowerCase().includes(B.toLowerCase())) blueInMedia = true;
  assert.ok(blueInMedia, 'PPTX equation picture carries the blue symbols (' + media.length + ' media files)');
  console.log('PASS PDF export, PPTX keeps the partial color of Sketch-to-Slides equations');
  console.log('ALL PASS');
} finally {
  socket?.close();
  await stopElectron(electron);
  await server.close();
}
